def render_workspace_guidance(application) -> None:
    """Render consistent contextual help for a registered application page."""
    details = GUIDANCE.get(application.key)
    if not details:
        return
    overview, steps, inputs, sample, output, errors = details
    with st.expander(f"ℹ️ Getting started with {application.name}", expanded=False):
        st.markdown(f"**What this does**\n\n{overview}")
        st.markdown(f"**How to use it**\n\n{steps}")
        st.markdown(f"**What you need**\n\n{inputs}")
        st.markdown(f"**Example to try**\n\n> {sample}")
        st.markdown(f"**What to expect**\n\n{output}")
        st.markdown(f"**If something goes wrong**\n\n{errors}")
        st.caption("Examples are illustrative guidance. Outputs depend on your data, model, permissions and connected services.")
